<script lang="ts">
  import {untrack} from 'svelte';
  import X from '@lucide/svelte/icons/x';
  import type {FieldDefinition,JsonValue} from '../../api/domain';
  import {updateField} from '../../api/workspace';
  import {cloneJson} from '../../util/json';
  import {focusDialog} from '../../util/focusDialog';
  import {requestConfirmation} from '../../confirmation';
  import {writable,fieldRules,optionDetails,type FormRules,type ConditionGroup,type OptionDetail} from '../../util/formRules';
  import ConditionGroupBuilder from './ConditionGroupBuilder.svelte';
  import RuleValueInput from './RuleValueInput.svelte';
  let {field,fields,moduleName,onClose,onSaved}:{field:FieldDefinition;fields:FieldDefinition[];moduleName:string;onClose:()=>void;onSaved:()=>Promise<void>}=$props();
  let rules=$state<FormRules>(untrack(()=>cloneJson(fieldRules(field))));
  let details=$state<OptionDetail[]>(untrack(()=>((field.config.options||[]) as string[]).map(value=>cloneJson(optionDetails(field).find(d=>d.value.toLowerCase()===value.toLowerCase())||{value,fill:{}}))));
  let presentation=$state(untrack(()=>String(field.config.presentation||'select')));let busy=$state(false);let error=$state('');let saved=false;
  const controllers=$derived(fields.filter(f=>f.active&&f.key!==field.key&&writable(f)));
  const destinations=$derived(controllers.filter(f=>f.field_type!=='relationship'));
  const conditions=[['visible_when','Show field when'],['enabled_when','Allow editing when'],['required_when','Require a value when']] as const;
  const snapshot=untrack(()=>JSON.stringify({rules,details,presentation}));
  async function close(){if(busy)return;if(!saved&&JSON.stringify({rules,details,presentation})!==snapshot&&!await requestConfirmation({title:'Discard unsaved form rules?',description:'Your record data has not been changed.',confirmLabel:'Discard rules',tone:'danger'}))return;onClose();}
  async function save(){busy=true;error='';try{const config={...field.config};delete config.form_rules;delete config.option_details;delete config.presentation;if(Object.keys(rules).length)config.form_rules=cloneJson(rules) as unknown as JsonValue;if(field.field_type==='select'){config.presentation=presentation;config.option_details=cloneJson(details.map(d=>{const clean=cloneJson(d);if(!clean.label?.trim())delete clean.label;else clean.label=clean.label.trim();return clean;}).filter(d=>d.label||d.number!==undefined||d.available_when||Object.keys(d.fill||{}).length)) as unknown as JsonValue;}await updateField(field.uid,{config});saved=true;await onSaved();onClose();}catch(reason){error=reason instanceof Error?reason.message:'Could not save these rules.';}finally{busy=false;}}
  function toggle(key:keyof FormRules,checked:boolean){const next={...rules};if(checked)next[key]={match:'all',conditions:[]} as never;else delete next[key];rules=next;}
  function condition(key:keyof FormRules,group:ConditionGroup){rules={...rules,[key]:group};}
</script>
<svelte:window onkeydown={e=>{if(e.key==='Escape'&&!document.querySelector('[role="alertdialog"]')){e.preventDefault();e.stopPropagation();void close();}}}/>
<div class="overlay" role="presentation" onclick={e=>{if(e.target===e.currentTarget)void close();}}>
  <div class="dialog rules-dialog" role="dialog" aria-modal="true" aria-labelledby="rules-title" tabindex="-1" use:focusDialog>
    <header class="dialog-head"><div><h2 id="rules-title">Form rules · {field.label}</h2><p class="muted small">{moduleName} · {field.key}</p></div><button type="button" class="icon-button" disabled={busy} aria-label="Close form rules" onclick={()=>void close()}><X size={18}/></button></header>
    {#if error}<div class="rule-error notice error" role="alert">{error}</div>{/if}
    <div class="rules-body"><p class="muted">Configure this field without code. Selections save as normal record cells and versions. Hidden ordinary values are cleared on save; users are warned before changing branches. Stored files are retained.</p>
      {#each conditions as [key,label]}{#if key==='visible_when'||writable(field)}<section><label class="checkbox"><input type="checkbox" checked={!!rules[key]} disabled={busy} onchange={e=>toggle(key,e.currentTarget.checked)}/>{label}</label>{#if rules[key]}<ConditionGroupBuilder group={rules[key]!} fields={controllers} disabled={busy} onChange={g=>condition(key,g)}/>{/if}</section>{/if}{/each}
      {#if !writable(field)}<p class="muted small">Calculated fields and attachments support visibility only. Uploads are separate from record saves; no file is automatically deleted.</p>{/if}
      {#if field.field_type==='boolean'}<section><h3>Exclusive checkbox group</h3><label>Group name<input disabled={busy} value={rules.exclusive_group||''} placeholder="Optional, e.g. Request type" oninput={e=>{const next={...rules};if(e.currentTarget.value.trim())next.exclusive_group=e.currentTarget.value;else{delete next.exclusive_group;delete next.exclusive_required;}rules=next;}}/></label><p class="muted small">Boolean fields in the same named group cannot both be selected. Selecting one clears the other checkboxes.</p><label class="checkbox"><input type="checkbox" disabled={busy||!rules.exclusive_group} checked={!!rules.exclusive_required} onchange={e=>rules={...rules,exclusive_required:e.currentTarget.checked}}/>Require one applicable choice in this group</label></section>{/if}
      {#if field.field_type==='select'}<section><h3>Choice appearance</h3><label>Display as<select disabled={busy} bind:value={presentation}><option value="select">Dropdown</option><option value="radio">Radio buttons (one choice)</option><option value="checkbox">Checkboxes (one choice)</option></select></label><p class="muted small">The stored option value stays the same. Labels are for display only; automatic values are editable copies, not live calculations.</p></section>
        <h3>Options and automatic values</h3>{#each details as detail,index}<details class="option-rule"><summary>{detail.label||detail.value}<small>Stored value: {detail.value}</small></summary><div class="option-body"><label>Display label<input disabled={busy} bind:value={detail.label} placeholder={detail.value}/></label><label>Numeric value for calculations (optional)<input type="number" step="any" disabled={busy} aria-label={`Numeric value for ${detail.value}`} value={detail.number ?? ''} oninput={event=>{const raw=event.currentTarget.value;if(raw==='')delete detail.number;else detail.number=Number(raw);}}/><small>Users select the label; numeric formulas use this value. For example, SL can have a value of 5.</small></label><label class="checkbox"><input type="checkbox" disabled={busy} checked={!!detail.available_when} onchange={e=>{if(e.currentTarget.checked)detail.available_when={match:'all',conditions:[]};else delete detail.available_when;}}/>Only offer this option when</label>{#if detail.available_when}<ConditionGroupBuilder group={detail.available_when} fields={controllers} disabled={busy} onChange={g=>detail.available_when=g}/>{/if}
          <h4>Fill these fields when selected</h4>{#each Object.entries(detail.fill||{}) as [key,value]}{@const target=destinations.find(f=>f.key===key)}<div class="mapping">{#if target}<RuleValueInput field={target} {value} label={target.label} disabled={busy} onChange={v=>detail.fill={...detail.fill,[key]:v}}/>{:else}<span>Unavailable destination: {key}</span>{/if}<button class="button small" type="button" disabled={busy} onclick={()=>{const next={...detail.fill};delete next[key];detail.fill=next;}}>Remove value</button></div>{/each}
          <label>Add a destination<select disabled={busy} aria-label={`Add destination for ${detail.value}`} value="" onchange={e=>{if(e.currentTarget.value)detail.fill={...detail.fill,[e.currentTarget.value]:null};e.currentTarget.value='';}}><option value="">Choose a field…</option>{#each destinations.filter(f=>!Object.hasOwn(detail.fill||{},f.key)) as target}<option value={target.key}>{target.label}</option>{/each}</select></label>
        </div></details>{/each}
      {/if}
    </div>
    <footer class="dialog-actions"><button class="button" type="button" disabled={busy} onclick={()=>void close()}>Cancel</button><button class="button" type="button" disabled={busy} onclick={()=>{rules={};details=details.map(d=>({value:d.value,fill:{}}));presentation='select';}}>Remove rules</button><span class="spacer"></span><button class="button primary" type="button" disabled={busy} onclick={()=>void save()}>{busy?'Saving…':'Save form rules'}</button></footer>
  </div>
</div>
<style>.rules-dialog{width:min(56rem,100%);max-height:calc(100dvh - 2rem);display:flex;flex-direction:column;padding:0;overflow:hidden}.dialog-head,.dialog-actions{padding:1rem;margin:0;flex-shrink:0}.dialog-head{border-bottom:1px solid var(--line)}h2{font-size:1.15rem;margin:0}.dialog-head p{margin:.3rem 0 0}.rules-body{padding:1rem;overflow:auto;min-height:0}.rules-body>p{margin-top:0}section{margin-bottom:1rem;display:grid;gap:.65rem}label:not(.checkbox){display:grid;gap:.35rem;font-size:.85rem;min-width:0}input,select{width:100%;min-width:0}input[type=checkbox]{width:auto}.checkbox{display:flex;gap:.5rem;align-items:center}h3{font-size:.95rem;margin:.35rem 0}h4{font-size:.85rem;margin:.75rem 0 .25rem}.option-rule{border:1px solid var(--line);border-radius:.5rem;margin:.65rem 0}.option-rule>summary{padding:.75rem;cursor:pointer;font-weight:600}.option-rule small{display:block;font-weight:400;color:var(--muted);margin-top:.25rem}.option-body{padding:0 .75rem .75rem;display:grid;gap:.65rem}.mapping{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:.5rem;align-items:end}.dialog-actions{border-top:1px solid var(--line);gap:.5rem}.rule-error{margin:.75rem 1rem 0;flex-shrink:0;max-height:25dvh;overflow:auto}@media(max-width:540px){.overlay{padding:.5rem}.rules-dialog{max-height:calc(100dvh - 1rem)}.dialog-actions{flex-wrap:wrap}.dialog-actions .spacer{display:none}.dialog-actions>button{flex:1}.mapping{grid-template-columns:minmax(0,1fr)}}
</style>
